package de.giesen.gva.watch;
import android.app.*;
import android.content.*;
import android.provider.Settings;
import java.util.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
import static org.robolectric.Shadows.shadowOf;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34)
public class WatchAlertsTest {
    Application c;NotificationManager manager;String session,token;long seq;
    @Before public void reset(){c=RuntimeEnvironment.getApplication();c.getSharedPreferences("watch_safety_v1",0).edit().clear().commit();c.getSharedPreferences(WatchAlerts.PREFS,0).edit().clear().commit();WatchConsent.accept(c,1);WatchConsent.accept(c,2);Settings.Global.putInt(c.getContentResolver(),"boot_count",1);manager=c.getSystemService(NotificationManager.class);shadowOf(manager).setNotificationsEnabled(true);shadowOf(c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);session=UUID.randomUUID().toString();token=UUID.randomUUID().toString();seq=0;}
    private WatchAlert event(WatchAlert.Action a,String id,String text,boolean test){return new WatchAlert(a,session,++seq,id,System.currentTimeMillis(),a==WatchAlert.Action.CLEAR?"":"Synthetic alarm",a==WatchAlert.Action.CLEAR?"":text,test);}
    private WatchAlert show(){return event(WatchAlert.Action.SHOW,token,"Synthetic receipt",false);}
    private Notification posted(){return shadowOf(manager).getNotification(WatchAlerts.ID);}
    @Test public void receptionRequiresSeparateOptInConsentAndAndroidPermission(){assertFalse(WatchAlerts.enabled(c));assertFalse(WatchAlerts.receive(c,show()));WatchAlerts.set(c,true);assertTrue(WatchAlerts.enabled(c));shadowOf(c).denyPermissions(android.Manifest.permission.POST_NOTIFICATIONS);assertFalse(WatchAlerts.receive(c,show()));assertNull(posted());shadowOf(c).grantPermissions(android.Manifest.permission.POST_NOTIFICATIONS);c.getSharedPreferences("watch_safety_v1",0).edit().clear().commit();assertFalse(WatchAlerts.receive(c,show()));}
    @Test public void newAlertIsDismissibleWithFiniteVibrationAndNoSound(){WatchAlerts.set(c,true);assertTrue(WatchAlerts.receive(c,show()));Notification n=posted();assertNotNull(n);assertEquals(0,n.flags&Notification.FLAG_ONGOING_EVENT);assertEquals(0,n.flags&Notification.FLAG_ONLY_ALERT_ONCE);assertTrue((n.flags&Notification.FLAG_LOCAL_ONLY)!=0);assertEquals(Notification.CATEGORY_ALARM,n.category);NotificationChannel ch=manager.getNotificationChannel(WatchAlerts.CHANNEL);assertNull(ch.getSound());assertTrue(ch.shouldVibrate());assertArrayEquals(new long[]{0,180,180,180},ch.getVibrationPattern());assertEquals(NotificationManager.IMPORTANCE_HIGH,ch.getImportance());}
    @Test public void duplicateAndOutOfOrderEventsCannotNotifyAgain(){WatchAlerts.set(c,true);WatchAlert a=show();assertTrue(WatchAlerts.receive(c,a));assertFalse(WatchAlerts.receive(c,a));assertFalse(WatchAlerts.receive(c,new WatchAlert(WatchAlert.Action.SHOW,session,1,UUID.randomUUID().toString(),a.issued,"Old","Old",false)));assertEquals(token,posted().extras.getString("gva_alert_token"));}
    @Test public void updatesAreQuietAndOldClearCannotRemoveANewerAlert(){WatchAlerts.set(c,true);assertTrue(WatchAlerts.receive(c,show()));assertTrue(WatchAlerts.receive(c,event(WatchAlert.Action.UPDATE,token,"Updated synthetic receipt",false)));assertTrue((posted().flags&Notification.FLAG_ONLY_ALERT_ONCE)!=0);assertEquals("Updated synthetic receipt",posted().extras.getCharSequence(Notification.EXTRA_TEXT).toString());String newer=UUID.randomUUID().toString();assertTrue(WatchAlerts.receive(c,event(WatchAlert.Action.SHOW,newer,"New phase",false)));assertTrue(WatchAlerts.receive(c,event(WatchAlert.Action.CLEAR,token,"",false)));assertNotNull(posted());assertTrue(WatchAlerts.receive(c,event(WatchAlert.Action.CLEAR,newer,"",false)));assertNull(posted());}
    @Test public void dismissingOnWatchCannotResurrectCardThroughValueUpdates()throws Exception{WatchAlerts.set(c,true);assertTrue(WatchAlerts.receive(c,show()));Notification n=posted();n.deleteIntent.send();shadowOf(android.os.Looper.getMainLooper()).idle();manager.cancel(WatchAlerts.ID);assertFalse(WatchAlerts.receive(c,event(WatchAlert.Action.UPDATE,token,"Updated",false)));assertNull(posted());assertNull(c.getSharedPreferences(WatchAlerts.PREFS,0).getString("active",null));}
    @Test public void staleAndUntrustedClockEventsDoNotProduceNotifications(){WatchAlerts.set(c,true);WatchAlert a=show();assertFalse(WatchAlerts.receive(c,new WatchAlert(a.action,a.session,a.sequence,a.token,System.currentTimeMillis()-30001,a.title,a.text,false)));Settings.Global.putInt(c.getContentResolver(),"boot_count",-1);assertFalse(WatchAlerts.receive(c,show()));assertNull(posted());}
    @Test public void turningOffClearsCardAndTurningOnDoesNotReplayIt(){WatchAlerts.set(c,true);WatchAlert a=show();assertTrue(WatchAlerts.receive(c,a));WatchAlerts.set(c,false);assertNull(posted());WatchAlerts.set(c,true);assertFalse(WatchAlerts.receive(c,a));assertNull(posted());assertFalse(WatchAlerts.receive(c,event(WatchAlert.Action.UPDATE,token,"Updated",false)));}
    @Test public void syntheticTestIsSeparateFromActualAlarmAndExpires(){WatchAlerts.set(c,true);assertTrue(WatchAlerts.receive(c,show()));assertTrue(WatchAlerts.receive(c,event(WatchAlert.Action.SHOW,UUID.randomUUID().toString(),"TEST – no reading",true)));assertEquals(token,posted().extras.getString("gva_alert_token"));assertEquals(15000,shadowOf(manager).getNotification(WatchAlerts.TEST_ID).getTimeoutAfter());assertEquals(0,posted().getTimeoutAfter());}
    @Test public void oldDisplayOnlyConsentsCannotEnableTheNewRelay(){c.getSharedPreferences("watch_safety_v1",0).edit().clear().putBoolean("warning",true).putBoolean("terms",true).commit();assertFalse(WatchConsent.ready(c));WatchConsent.accept(c,2);assertFalse(WatchConsent.ready(c));WatchConsent.accept(c,1);assertFalse(WatchConsent.ready(c));WatchConsent.accept(c,2);assertTrue(WatchConsent.ready(c));assertFalse(WatchAlerts.enabled(c));}
    @Test public void textAndValuesAreNotPersistedInTheReplayLedger(){WatchAlerts.set(c,true);assertTrue(WatchAlerts.receive(c,show()));String stored=c.getSharedPreferences(WatchAlerts.PREFS,0).getAll().toString();assertFalse(stored.contains("Synthetic"));assertFalse(stored.contains("receipt"));}
}
